// C/C++ N-Dimensional Array Memory Layout (Row-Major)

#define DIM_R 4
#define DIM_C 8
int A[DIM_R][DIM_C]; // A[row][col]

// Accessing A[i][j] where i=2, j=3

// 1. Offset Calculation (in element units):
// Offset = (Row Index * Elements Per Row) + Column Index
// R_Offset = i * DIM_C
// Total_Offset = R_Offset + j
size_t offset = (2 * DIM_C) + 3;

// 2. Equivalent Pointer Arithmetic:
// Base + Total_Offset
int* element_ptr = (int*)A + offset;

// Optimization Hint: For Row-Major, inner loop should traverse columns (j)
// to ensure linear memory access and better cache utilization.
for (int i=0; i<DIM_R; i++) {
    for (int j=0; j<DIM_C; j++) {
        A[i][j]; // Efficient access pattern
    }
}
